          pfc->value[gedf_unknown_indices[gedf_index]][0] = '\0';
        }
        previous_x = atof(pfc->value[gedf_unknown_indices[gedf_index]]);

        class_call(parser_init_from_pfc(pfc, &(fzw.fc), errmsg),
                   errmsg,
                   errmsg);

        /* input_get_guess() expects the one unknown entry to be last, since it
           temporarily hides the final target_size entries while reading the
           known parameters. Move the density being shot to that position in
           the private file-content copy; the original ordering is unchanged. */
        last_index = fzw.fc.size - 1;
        if (gedf_unknown_indices[gedf_index] != last_index) {
          strcpy(swap_name, fzw.fc.name[last_index]);
          strcpy(swap_value, fzw.fc.value[last_index]);
          swap_read = fzw.fc.read[last_index];
          strcpy(fzw.fc.name[last_index], fzw.fc.name[gedf_unknown_indices[gedf_index]]);
          strcpy(fzw.fc.value[last_index], fzw.fc.value[gedf_unknown_indices[gedf_index]]);
          fzw.fc.read[last_index] = fzw.fc.read[gedf_unknown_indices[gedf_index]];
          strcpy(fzw.fc.name[gedf_unknown_indices[gedf_index]], swap_name);
          strcpy(fzw.fc.value[gedf_unknown_indices[gedf_index]], swap_value);
          fzw.fc.read[gedf_unknown_indices[gedf_index]] = swap_read;
        }

        fzw.target_size = 1;
        fzw.required_computation_stage = cs_background;
        class_alloc(fzw.unknown_parameters_index, sizeof(int), errmsg);
        class_alloc(fzw.target_name, sizeof(enum target_names), errmsg);
        class_alloc(fzw.target_value, sizeof(double), errmsg);

        fzw.unknown_parameters_index[0] = last_index;
        fzw.target_name[0] = gedf_target_names[gedf_index];
        fzw.target_value[0] = gedf_target_values[gedf_index];

        if (input_verbose > 0) {
          printf("Computing unknown input parameter '%s' using input parameter '%s' (separate H0 shooting, pass %d)\n",
                 gedf_unknown_namestrings[gedf_index],
                 gedf_target_namestrings[gedf_index],
                 gedf_iteration + 1);
        }

        xzero = previous_x;
        class_call_try(input_find_root(&xzero,
                                       &fevals,
                                       ppr->tol_shooting_deltax_rel,
                                       &fzw,
                                       errmsg),
                       errmsg,
                       pba->shooting_error,
                       shooting_failed=_TRUE_);

        class_sprintf(pfc->value[gedf_unknown_indices[gedf_index]],"%.20e",xzero);
        max_relative_change = MAX(max_relative_change,
                                  fabs(xzero-previous_x)/MAX(fabs(xzero),1.));
        if ((input_verbose > 0) && (shooting_failed == _FALSE_)) {
          printf(" -> found '%s = %s'\n",
                 gedf_unknown_namestrings[gedf_index],
                 pfc->value[gedf_unknown_indices[gedf_index]]);
        }

        class_call(parser_free(&(fzw.fc)), errmsg, errmsg);
        free(fzw.unknown_parameters_index);
        free(fzw.target_name);
        free(fzw.target_value);

        if (shooting_failed == _TRUE_)
          break;
      }

      if ((gedf_active_count < 2)
          || (max_relative_change < ppr->tol_shooting_deltax_rel))
        gedf_converged = _TRUE_;
    }

    if ((shooting_failed == _FALSE_) && (gedf_converged == _FALSE_)) {
      class_sprintf(pba->shooting_error,
                    "Separate H0 shooting of f_gedf did not converge after %d passes.",
                    gedf_iteration);
      shooting_failed = _TRUE_;
    }
    if ((input_verbose > 1) && (shooting_failed == _FALSE_))
      printf("Separate H0 GEDF shooting converged in %d passes using %d function evaluations\n",
             gedf_iteration,
             fevals);
    pba->shooting_failed = shooting_failed;
  }

}

/**
 * Free all memory space allocated by background_init() and by input_read_parameters().
 *
 *
 * @param pba Input: pointer to background structure (to be freed)
 * @return the error status
 */

int background_free(
                    struct background *pba
                    ) {

  class_call(background_free_noinput(pba),
             pba->error_message,
             pba->error_message);

  class_call(background_free_input(pba),
             pba->error_message,
             pba->error_message);

  pba->is_allocated = _FALSE_;

  return _SUCCESS_;
}

/**
 * Free only the memory space NOT allocated through
 * input_read_parameters(), but through background_init()
 *
 * @param pba Input: pointer to background structure (to be freed)
 * @return the error status
 */

int background_free_noinput(
                            struct background *pba
                            ) {

  free(pba->tau_table);
  free(pba->z_table);
  free(pba->loga_table);
  free(pba->d2tau_dz2_table);
  free(pba->d2z_dtau2_table);
  free(pba->background_table);
  free(pba->d2background_dloga2_table);

  return _SUCCESS_;
}
